/*
 * Real implementations of the .so->Java callbacks the boot path depends on.
 * Each one mirrors the jadx source it replaces (file:line in the comment);
 * java.c points its method tables here instead of the no-op stubs in
 * generated_jni_stubs.c (which stays autogenerated and untouched).
 */

#include <falso_jni/FalsoJNI.h>
#include <falso_jni/FalsoJNI_Impl.h>
#include <falso_jni/FalsoJNI_ImplBridge.h>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "utils/logger.h"

#ifndef DATA_PATH
#define DATA_PATH "ux0:data/nova2/"
#endif

// ---- helpers -------------------------------------------------------------

static jbyteArray bytes_from_buf(const void *buf, jsize len) {
    jbyteArray arr = jni->NewByteArray(&jni, len);
    if (arr && len > 0)
        memcpy(((JavaDynArray *)arr)->array, buf, len);
    return arr;
}

static jbyteArray bytes_from_cstr(const char *s) {
    return bytes_from_buf(s, strlen(s));
}

// GLResLoader: strip "./" or ".//", trim, then AssetManager.open(path) ->
// DATA_PATH "assets/<path>". The res_<name> drawable lookup always misses
// (the APK has no res_* drawables), so only the asset branch is reproduced.
static FILE *open_asset(jstring jpath, char *out, size_t outsz) {
    if (!jpath)
        return NULL;
    const char *p = jni->GetStringUTFChars(&jni, jpath, NULL);
    if (!p)
        return NULL;

    const char *s = p;
    if (strncmp(s, ".//", 3) == 0) s += 3;
    else if (strncmp(s, "./", 2) == 0) s += 2;
    while (*s == ' ' || *s == '\t') s++;

    snprintf(out, outsz, DATA_PATH "assets/%s", s);
    jni->ReleaseStringUTFChars(&jni, jpath, p);

    size_t n = strlen(out);
    while (n > 0 && (out[n - 1] == ' ' || out[n - 1] == '\t' ||
                     out[n - 1] == '\r' || out[n - 1] == '\n'))
        out[--n] = '\0';

    FILE *f = fopen(out, "rb");
    if (!f)
        l_warn("GLResLoader: asset not found: %s", out);
    return f;
}

static long file_len(FILE *f) {
    fseek(f, 0, SEEK_END);
    long len = ftell(f);
    fseek(f, 0, SEEK_SET);
    return len;
}

static jbyteArray read_range(FILE *f, long off, long len) {
    jbyteArray arr = jni->NewByteArray(&jni, len);
    if (!arr)
        return NULL;
    if (off > 0)
        fseek(f, off, SEEK_SET);
    fread(((JavaDynArray *)arr)->array, 1, len, f);
    return arr;
}

// R.raw.raw_000 + i -> res/raw/raw_%03d.ogg
static FILE *open_sound_raw(int i, char *out, size_t outsz) {
    snprintf(out, outsz, DATA_PATH "res/raw/raw_%03d.ogg", i);
    FILE *f = fopen(out, "rb");
    if (!f)
        l_warn("GLResLoader: raw sound not found: %s", out);
    return f;
}

// ---- GLGame / Device -----------------------------------------------------

// GLGame.java:266 -- returns GLGame.b, forced to "atc" in
// GameRenderer.onSurfaceCreated (GameRenderer.java:124); the .gla packs of
// this build ship ATC textures.
jobject impl_GLGame_getTextureCompression(jmethodID id, va_list args) {
    return bytes_from_cstr("atc");
}

// GLGame.java:270
jobject impl_GLGame_getVersion(jmethodID id, va_list args) {
    return bytes_from_cstr("1.0.5");
}

// GLGame.java:239 (MANUFACTURER_DEVICE) / Device.java:188 (MODEL_PRODUCT)
jobject impl_GLGame_getHostName(jmethodID id, va_list args) {
    return bytes_from_cstr("Sony_PSVita");
}

// GLGame.java:299 returns 1, which on Android turns on Gameloft's
// ALicenseCheck (config/RMS files + HTTP validation). No license server on
// the Vita: report "no native DRM" so GLGame.nativeInit skips it (patch.c
// also neutralizes the ALicenseCheck entry points).
jint impl_GLGame_isUseNativeDRM(jmethodID id, va_list args) {
    return 0;
}

// ---- GLResLoader ---------------------------------------------------------

// GLResLoader.getResourceFull(String)[B
jobject impl_GLResLoader_getResourceFull(jmethodID id, va_list args) {
    jstring path = va_arg(args, jstring);
    char real[512];
    FILE *f = open_asset(path, real, sizeof(real));
    if (!f)
        return NULL;
    jbyteArray arr = read_range(f, 0, file_len(f));
    fclose(f);
    return arr;
}

// GLResLoader.getResourceBytes(String, int offset, int len)[B
jobject impl_GLResLoader_getResourceBytes(jmethodID id, va_list args) {
    jstring path = va_arg(args, jstring);
    int off = va_arg(args, int);
    int len = va_arg(args, int);
    char real[512];
    FILE *f = open_asset(path, real, sizeof(real));
    if (!f)
        return NULL;
    jbyteArray arr = read_range(f, off, len);
    fclose(f);
    return arr;
}

// GLResLoader.getResourceLength(String)I -- 0 when missing, like the Java.
jint impl_GLResLoader_getResourceLength(jmethodID id, va_list args) {
    jstring path = va_arg(args, jstring);
    char real[512];
    FILE *f = open_asset(path, real, sizeof(real));
    if (!f)
        return 0;
    long len = file_len(f);
    fclose(f);
    return (jint)len;
}

// GLResLoader.getSoundRaw(I)[B
jobject impl_GLResLoader_getSoundRaw(jmethodID id, va_list args) {
    int i = va_arg(args, int);
    char real[256];
    FILE *f = open_sound_raw(i, real, sizeof(real));
    if (!f)
        return NULL;
    jbyteArray arr = read_range(f, 0, file_len(f));
    fclose(f);
    return arr;
}

// GLResLoader.getResourceLengthSoundRaw(I)I
jint impl_GLResLoader_getResourceLengthSoundRaw(jmethodID id, va_list args) {
    int i = va_arg(args, int);
    char real[256];
    FILE *f = open_sound_raw(i, real, sizeof(real));
    if (!f)
        return 0;
    long len = file_len(f);
    fclose(f);
    return (jint)len;
}
